"""Deterministic geography-balanced catalogue reduction; never rerun on reduced input."""
import json,math,re,subprocess,collections
from pathlib import Path
root=Path(__file__).resolve().parents[1]
base='9dc0dec'
def old(path):return subprocess.check_output(['git','show',base+':'+path],cwd=root,text=True)
def records(prefix):
 names=['supabase/functions/_shared/worldData/'+name for name in re.findall(r'from "./worldData/([^"]+)"',old('supabase/functions/_shared/worldDefinitions.ts'))]
 return [row for name in names if Path(name).name.startswith(prefix+'-') for row in json.loads(old(name).split(' = ',1)[1].removesuffix(';\n'))]
cities=records('cityDefinitions');provinces=records('provinceDefinitions');points=json.loads(old('src/world/data/city-points.json'));coords={c['id']:c['point'] for c in points}
count=len(cities);target=math.floor(count*.75+.5);by={c['id']:c for c in cities};groups=collections.defaultdict(list);countries=collections.defaultdict(list)
for c in cities:groups[c['provinceId']].append(c);countries[c['countryId']].append(c)
important={'rotterdam','hamburg','marseille','istanbul','singapore','shanghai','hong kong','new york','los angeles','mumbai','santos','antwerp','busan','osaka','yokohama','durban','cape town','vancouver','sydney','melbourne','barcelona','genoa','valencia','lisbon','san francisco'}
protected={c['id'] for c in cities if c['isCapital'] or c['isRegionalCapital'] or c['population']>=500000 or c['name'].lower() in important}
for rows in groups.values():protected.add(max(rows,key=lambda c:(c['population'],c['isCapital'],c['id']))['id'])
assert len(protected)<=target,(len(protected),target)
candidates={k:[c for c in rows if c['id'] not in protected] for k,rows in countries.items()}
quotas={k:min(len(candidates[k]),math.floor(len(rows)*.25)) for k,rows in countries.items()}
while sum(quotas.values())<count-target:
 k=max((k for k in quotas if quotas[k]<len(candidates[k])),key=lambda k:(len(countries[k])*.25-quotas[k],-quotas[k]/len(countries[k]),k));quotas[k]+=1
while sum(quotas.values())>count-target:
 k=max((k for k in quotas if quotas[k]),key=lambda k:(quotas[k]-len(countries[k])*.25,k));quotas[k]-=1
cells=collections.Counter((c['countryId'],math.floor(coords[c['id']][0]/8),math.floor(coords[c['id']][1]/8)) for c in cities)
remove=set()
for k,rows in candidates.items():
 rows.sort(key=lambda c:(c['population']/(1+.18*cells[(k,math.floor(coords[c['id']][0]/8),math.floor(coords[c['id']][1]/8))]),c['population'],c['id']))
 remove.update(c['id'] for c in rows[:quotas[k]])
assert len(remove)==count-target and not remove&protected
kept={c['id']:dict(c) for c in cities if c['id'] not in remove};mapping={}
for c in cities:
 if c['id'] not in remove:continue
 options=[v for v in groups[c['provinceId']] if v['id'] in kept];assert options
 x,y=coords[c['id']];replacement=min(options,key=lambda v:((coords[v['id']][0]-x)**2+(coords[v['id']][1]-y)**2,v['id']))
 mapping[c['id']]=replacement['id'];v=kept[replacement['id']];total=v['population']+c['population']
 v['development']=(v['development']*v['population']+c['development']*c['population'])/total if total else v['development'];v['population']=total
for p in provinces:p['cityIds']=[id for id in p['cityIds'] if id in kept]
rows=sorted(kept.values(),key=lambda c:c['id'])
assert len(rows)==target and sum(c['population'] for c in rows)==sum(c['population'] for c in cities)
for pid,original in groups.items():assert sum(c['population'] for c in original)==sum(c['population'] for c in rows if c['provinceId']==pid)
world=root/'supabase/functions/_shared/worldData'
for prefix,kind,values,chunk in [('cityDefinitions','CityDefinition',rows,200),('provinceDefinitions','ProvinceDefinition',provinces,100)]:
 for p in world.glob(prefix+'-*.ts'):p.unlink()
 for i in range(0,len(values),chunk):
  (world/f'{prefix}-{i//chunk:02d}.ts').write_text(f'import type {{ {kind} }} from "../worldDefinitions.ts";\nexport const data: {kind}[] = '+json.dumps(values[i:i+chunk],ensure_ascii=False,separators=(',',':'))+';\n')
p=root/'supabase/functions/_shared/worldDefinitions.ts';s=p.read_text();s=re.sub(r'^import \{data as cityDefinitionsBatch\d+\}.*\n','',s,flags=re.M);s=re.sub(r'^export const cityDefinitions:.*\n','',s,flags=re.M)
batches=[]
for i in range(math.ceil(len(rows)/200)):
 batch='cityDefinitionsBatch'+str(i);s+=f'import {{data as {batch}}} from "./worldData/cityDefinitions-{i:02d}.ts";\n';batches.append('...'+batch)
s+='export const cityDefinitions: readonly CityDefinition[] = ['+','.join(batches)+'];\n';p.write_text(s)
(root/'src/world/data/city-points.json').write_text(json.dumps([c for c in points if c['id'] in kept],separators=(',',':'))+'\n')
# Migration map is shared with server; stable survivor IDs/capitals never renumbered.
(root/'supabase/functions/_shared/cityReductionMap.ts').write_text('// Generated by scripts/reduce-cities.py; v4 city IDs to nearest retained center in same province.\nexport const removedCityMapping:Readonly<Record<string,string>>='+json.dumps(mapping,separators=(',',':'))+';\n')
report={'baseCommit':base,'before':count,'target':target,'after':len(rows),'reductionPercent':100*(1-len(rows)/count),'capitalsBefore':sum(c['isCapital'] for c in cities),'capitalsAfter':sum(c['isCapital'] for c in rows),'regionalCentersBefore':sum(c['isRegionalCapital'] for c in cities),'regionalCentersAfter':sum(c['isRegionalCapital'] for c in rows),'protected':len(protected),'provincePopulationBefore':sum(p['population'] for p in provinces),'provincePopulationAfter':sum(p['population'] for p in provinces),'urbanPopulationBefore':sum(c['population'] for c in cities),'urbanPopulationAfter':sum(c['population'] for c in rows),'countryDistribution':{k:{'before':len(v),'after':len(v)-quotas[k]} for k,v in sorted(countries.items())},'method':'country quotas, protected capitals/regional/major/port names and one city per populated province; remove low-population dense candidates; transfer urban population within same province; stable survivor IDs'}
(root/'CITY_REDUCTION_VISUAL.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='countryDistribution'},indent=2))
